mapper.update:
UPDATE CM_NTT_POPUP
   SET XCNTS = #{xcnts}
     , YDNTS = #{ydnts}
     , WIDTH = #{width}
     , VRTICL = #{vrticl}
     , START_DT = STR_TO_DATE(#{startDt}, '%Y-%m-%d %H:%i:%s')NULL
     , END_DT = STR_TO_DATE(#{endDt}, '%Y-%m-%d %H:%i:%s')NULL
     , HIDE_FL = #{hideFl}
     , USE_FL = #{useFl}
 WHERE CMPNY_CD = #{cmpnyCd}
   AND BBS_ID = #{bbsId}
   AND NTT_SQ = CAST(#{nttSq} AS DECIMAL(30,0))

mapper.delete:
DELETE FROM CM_NTT_POPUP
 WHERE CMPNY_CD = #{cmpnyCd}
   AND BBS_ID = #{bbsId}
   AND NTT_SQ = CAST(#{nttSq} AS DECIMAL(30,0))

mapper.update:
UPDATE CM_NTT N
   SET N.DELETE_FL = 'Y'
     , N.UPDATE_ID = #{updateId}
     , N.UPDATE_DT = CURRENT_TIMESTAMP
 WHERE N.CMPNY_CD = #{cmpnyCd}
   AND N.BBS_ID = #{bbsId}
   AND N.NTT_SQ = CAST(#{nttSq} AS DECIMAL(30,0))
   AND N.DELETE_FL = 'N'
   AND IFNULL(N.USE_FL, 'Y') = 'Y'
   AND (
           N.CREATION_ID = #{userId}
        OR #{managerOverride} = 1
       )

UPDATE CM_FILE F
 INNER JOIN CM_NTT N
    ON N.NTT_SQ = F.REFER_SQ
   AND N.BBS_ID = #{bbsId}
   AND N.CMPNY_CD = #{cmpnyCd}
   SET F.USE_FL = 'N'
     , F.UPDATE_ID = #{updateId}
 WHERE F.FILE_TY = 'BBS'
   AND F.SAVE_TY = 'DATA'
   AND IFNULL(F.USE_FL, 'Y') = 'Y'
   AND N.NTT_SQ = CAST(#{nttSq} AS DECIMAL(30,0))
   AND N.BBS_ID = #{bbsId}
   AND N.CMPNY_CD = #{cmpnyCd}

UPDATE CM_NTT
   SET RD_CNT = (
           SELECT COUNT(*)
             FROM CM_NTT_VIEW
            WHERE NTT_SQ = CAST(#{nttSq} AS DECIMAL(30,0))
              AND BBS_ID = #{bbsId}
              AND CMPNY_CD = #{cmpnyCd}
       )
     , LIKE_CNT = (
           SELECT COUNT(*)
             FROM CM_NTT_VOTE
            WHERE NTT_SQ = CAST(#{nttSq} AS DECIMAL(30,0))
              AND BBS_ID = #{bbsId}
              AND CMPNY_CD = #{cmpnyCd}
              AND VOTE_GB = 'L'
       )
     , DISLIKE_CNT = (
           SELECT COUNT(*)
             FROM CM_NTT_VOTE
            WHERE NTT_SQ = CAST(#{nttSq} AS DECIMAL(30,0))
              AND BBS_ID = #{bbsId}
              AND CMPNY_CD = #{cmpnyCd}
              AND VOTE_GB = 'D'
       )
     , FAVORITE_CNT = (
           SELECT COUNT(*)
             FROM CM_NTT_FAVORITE
            WHERE NTT_SQ = CAST(#{nttSq} AS DECIMAL(30,0))
              AND BBS_ID = #{bbsId}
              AND CMPNY_CD = #{cmpnyCd}
       )
 WHERE NTT_SQ = CAST(#{nttSq} AS DECIMAL(30,0))
   AND BBS_ID = #{bbsId}
   AND CMPNY_CD = #{cmpnyCd}

mapper.insert:
INSERT IGNORE INTO CM_NTT_VOTE (NTT_SQ, BBS_ID, CMPNY_CD, MBRSH_SQ, VOTE_GB)
SELECT CAST(#{nttSq} AS DECIMAL(30,0)), #{bbsId}, #{cmpnyCd}, M.MBRSH_SQ, #{voteGb}
  FROM CM_USER_ORGNZT_MBRSH M
  INNER JOIN CM_USER U ON U.USER_ID = M.USER_ID
 WHERE M.CMPNY_CD = #{cmpnyCd}
   AND M.USER_ID = #{userId}
   AND M.USE_FL = 'Y'
 LIMIT 1

mapper.select:
SELECT COUNT(*)
  FROM CM_NTT_VOTE V
 WHERE V.NTT_SQ = CAST(#{nttSq} AS DECIMAL(30,0))
   AND V.BBS_ID = #{bbsId}
   AND V.CMPNY_CD = #{cmpnyCd}
   AND V.VOTE_GB = #{voteGb}
   AND V.MBRSH_SQ = (
       SELECT M.MBRSH_SQ
         FROM CM_USER_ORGNZT_MBRSH M
         INNER JOIN CM_USER U ON U.USER_ID = M.USER_ID
        WHERE M.CMPNY_CD = #{cmpnyCd}
          AND M.USER_ID = #{userId}
          AND M.USE_FL = 'Y'
        LIMIT 1
   )

SELECT COUNT(*)
  FROM CM_NTT_FAVORITE F
 WHERE F.NTT_SQ = CAST(#{nttSq} AS DECIMAL(30,0))
   AND F.BBS_ID = #{bbsId}
   AND F.CMPNY_CD = #{cmpnyCd}
   AND F.MBRSH_SQ = (
       SELECT M.MBRSH_SQ
         FROM CM_USER_ORGNZT_MBRSH M
         INNER JOIN CM_USER U ON U.USER_ID = M.USER_ID
        WHERE M.CMPNY_CD = #{cmpnyCd}
          AND M.USER_ID = #{userId}
          AND M.USE_FL = 'Y'
        LIMIT 1
   )

