mapper.select:
SELECT COUNT(*)
  FROM CM_NTT_COMMENT
 WHERE CMPNY_CD = #{cmpnyCd}
   AND BBS_ID = #{bbsId}
   AND NTT_SQ = CAST(#{nttSq} AS DECIMAL(30,0))
   AND COMMENT_SQ = CAST(#{commentSq} AS DECIMAL(30,0))
   AND CREATION_ID = #{userId}
   AND IFNULL(USE_FL, 'Y') = 'Y'
   AND IFNULL(COMMENT, '') != '삭제된 글입니다.'

mapper.update:
UPDATE CM_NTT_COMMENT
   SET COMMENT = #{comment}
     , SECRET_FL = IFNULL(#{secretFl}, 'N')
     , UPDATE_ID = #{updateId}
     , UPDATE_DT = CURRENT_TIMESTAMP
 WHERE CMPNY_CD = #{cmpnyCd}
   AND BBS_ID = #{bbsId}
   AND NTT_SQ = CAST(#{nttSq} AS DECIMAL(30,0))
   AND COMMENT_SQ = CAST(#{commentSq} AS DECIMAL(30,0))
   AND IFNULL(USE_FL, 'Y') = 'Y'
   AND IFNULL(COMMENT, '') != '삭제된 글입니다.'
